    function wrap(tr){ var half = tr.scrollWidth / 2; if (half <= 0) return; while (off <= -half) off += half; while (off > 0) off -= half; tr.style.transform = 'translateX(' + off + 'px)'; }
    function hold(){ holdUntil = performance.now() + 2500; }
    function step(ts){
      var tr = document.getElementById('net-track');
      if (last === null) last = ts;
      var dt = Math.min((ts - last) / 1000, 0.1); last = ts;
      if (tr) {
        if (pending !== 0) { var mv = pending * Math.min(1, dt * 8); pending = Math.abs(pending - mv) < 0.5 ? 0 : pending - mv; off += mv; wrap(tr); }
        else if (!reduced && !hover && !drag && ts > holdUntil) { off -= 40 * dt; wrap(tr); }
      }
      requestAnimationFrame(step);
    }
