      marqueeTrack.querySelectorAll('.marquee-credit').forEach(function(el){
        el.textContent = t.gallery.photoBy + t.gallery.photographers[el.getAttribute('data-credit')];
      });
      var pc = PROJECTS[lang] || PROJECTS.en;
      marqueeTrack.querySelectorAll('.marquee-item').forEach(function(el){
        var key = projectOf(+el.getAttribute('data-photo')); var p = key && pc.projects[key];
        if (p) { el.querySelector('.marquee-pill').textContent = '+'; var pos = PLUS_POS[+el.getAttribute('data-photo')]; if (pos) el.classList.add('plus-' + pos); el.setAttribute('aria-label', p.name + ', ' + pc.hint); }
      });
      currentLang = lang;
