    var marqueeNextBtn = document.getElementById('marquee-next');
    if (marqueePrevBtn) marqueePrevBtn.setAttribute('aria-label', t.gallery.prev);
    if (marqueeNextBtn) marqueeNextBtn.setAttribute('aria-label', t.gallery.next);

    document.getElementById('pov-statement').textContent = t.pov.statement;

